param([Parameter(Mandatory=$true)][string]$FirstReport,[Parameter(Mandatory=$true)][string]$SecondReport)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$repo=$PSScriptRoot;while(-not [IO.File]::Exists((Join-Path $repo 'bootstrap/tools/verification.ps1'))){$parent=Split-Path $repo -Parent;if(-not $parent -or $parent -eq $repo){throw 'Repository root not found'};$repo=$parent};. (Join-Path $repo 'bootstrap/tools/verification.ps1')
$first=[IO.File]::ReadAllText($FirstReport)|ConvertFrom-Json;$second=[IO.File]::ReadAllText($SecondReport)|ConvertFrom-Json
if(-not $first.success -or -not $second.success){throw 'Two successful preserved observation reports required'}
$other=@{};foreach($record in $second.records){$key=$record.id;if(@($record.PSObject.Properties.Name) -contains 'jobs'){$key+=':'+$record.jobs};if($other.ContainsKey($key)){throw 'Duplicate second observation identity'};$other[$key]=$record}
$errors=New-Object Collections.Generic.List[string];$comparisons=New-Object Collections.Generic.List[object]
if($first.records.Count -ne $second.records.Count){$errors.Add('Different observation inventories')}
foreach($record in $first.records){$key=$record.id;if(@($record.PSObject.Properties.Name) -contains 'jobs'){$key+=':'+$record.jobs};if(-not $other.ContainsKey($key)){$errors.Add("Missing observation $key");continue};$partner=$other[$key];$left=Get-ArtifactIdentity $record.observation.path;$right=Get-ArtifactIdentity $partner.observation.path;if($left.sha256 -cne $record.observation.sha256 -or $right.sha256 -cne $partner.observation.sha256){$errors.Add("Changed preserved observation $key")};$same=$left.sha256 -ceq $right.sha256;if(-not $same){$errors.Add("Complete scalar stream differs $key")};if(@($record.PSObject.Properties.Name) -contains 'source'){if($record.source.sha256 -cne $partner.source.sha256){$errors.Add("Original source differs $key")}};$comparisons.Add([pscustomobject]@{identity=$key;equal=$same;first=$left;second=$right})}
$output=Join-Path (Split-Path $FirstReport -Parent) ('stage-comparison-'+[Guid]::NewGuid().ToString('N')+'.json');[pscustomobject]@{success=($errors.Count -eq 0);qualified=$false;diagnosticOnly=$true;firstReport=(Get-ArtifactIdentity $FirstReport);secondReport=(Get-ArtifactIdentity $SecondReport);comparator=(Get-ArtifactIdentity $PSCommandPath);comparisons=$comparisons.ToArray();errors=$errors.ToArray();limits='Complete emitted scalar observation bytes compared across two preserved successful native runs; language expectations remain in their separate independent selected/complete comparators.'}|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $output -Encoding UTF8
Write-Output "Evidence: $output";if($errors.Count -gt 0){throw ($errors -join '; ')}
